CREATE TABLE CW_INVOICE_SMTP_SETTINGS (SINGLETON_ID SMALLINT NOT NULL PRIMARY KEY, SMTP_HOST VARCHAR(255) NOT NULL, SMTP_PORT INTEGER NOT NULL, SMTP_FROM VARCHAR(320) NOT NULL, SMTP_USERNAME VARCHAR(320), START_TLS SMALLINT NOT NULL, UPDATED_AT TIMESTAMP NOT NULL, CONSTRAINT CW_INV_SMTP_SINGLETON CHECK (SINGLETON_ID = 1));
